schema:
CREATE TABLE ITP (
    ITEMN INT,
    PONUM INT
);
CREATE TABLE ITM (
    ITEMN INT,
    TYPE INT,
    PRIMARY KEY (ITEMN)
);
CREATE TABLE PUR (
    PONUM INT,
    ODATE INT,
    VENDN INT
);

CREATE TABLE R1 (
    A INT,
    B INT
);
CREATE TABLE R2 (
    A INT,
    B INT,
    PRIMARY KEY (A)
);

CREATE TABLE ITP (
    ITEMNO INT,
    NP INT
);
